        mismatches.append(f"{nid} confirmation_evidence.evaluated_digest stale")
    for k, want in (("confirmation_status","confirmed"),("evaluation_status","pass")):
        if n.get(k) != want: mismatches.append(f"{nid}.{k}={n.get(k)}")
    if n["implementation_readiness"]["status"] != "complete":
